from pathlib import Path
import hashlib,json,plistlib
root=Path(__file__).resolve().parent
app=root/'ResearchRadar'
def uid(s):return hashlib.sha1(s.encode()).hexdigest()[:24].upper()
objects=[]
def add(key,body):objects.append(f'{uid(key)} = {{ {body} }};')
sources=sorted((app/'Sources').glob('*.swift'))
resources=['Resources/Assets.xcassets','Resources/ReadingShelf.json','Resources/PrivacyInfo.xcprivacy']
for file in sources:
    rel='Sources/'+file.name;add(rel,f'isa = PBXFileReference; lastKnownFileType = sourcecode.swift; path = "{rel}"; sourceTree = "<group>";')
    add('build:'+rel,f'isa = PBXBuildFile; fileRef = {uid(rel)};')
for rel in resources:
    kind='folder.assetcatalog' if rel.endswith('xcassets') else 'text.plist.xml' if rel.endswith('xcprivacy') else 'text.json'
    add(rel,f'isa = PBXFileReference; lastKnownFileType = {kind}; path = "{rel}"; sourceTree = "<group>";')
    add('build:'+rel,f'isa = PBXBuildFile; fileRef = {uid(rel)};')
add('product','isa = PBXFileReference; explicitFileType = wrapper.application; includeInIndex = 0; path = ResearchRadar.app; sourceTree = BUILT_PRODUCTS_DIR;')
add('appgroup','isa = PBXGroup; path = ResearchRadar; sourceTree = "<group>"; children = ('+','.join(uid('Sources/'+p.name) for p in sources)+','+','.join(uid(r) for r in resources)+');')
add('products',f'isa = PBXGroup; name = Products; sourceTree = "<group>"; children = ({uid("product")});')
add('main',f'isa = PBXGroup; sourceTree = "<group>"; children = ({uid("appgroup")},{uid("products")});')
for key,isa,files in [('sources','PBXSourcesBuildPhase',['Sources/'+p.name for p in sources]),('resources','PBXResourcesBuildPhase',resources),('frameworks','PBXFrameworksBuildPhase',[])]:
    add(key,f'isa = {isa}; buildActionMask = 2147483647; files = ('+','.join(uid('build:'+r) for r in files)+'); runOnlyForDeploymentPostprocessing = 0;')
for mode in ['Debug','Release']:
    add('project'+mode,'isa = XCBuildConfiguration; name = '+mode+'; buildSettings = { CLANG_ENABLE_MODULES = YES; SWIFT_VERSION = 5.0; IPHONEOS_DEPLOYMENT_TARGET = 17.0; SDKROOT = iphoneos; '+('SWIFT_OPTIMIZATION_LEVEL = "-Onone"; DEBUG_INFORMATION_FORMAT = dwarf; SWIFT_ACTIVE_COMPILATION_CONDITIONS = DEBUG;' if mode=='Debug' else 'SWIFT_COMPILATION_MODE = wholemodule; SWIFT_OPTIMIZATION_LEVEL = "-O"; DEBUG_INFORMATION_FORMAT = "dwarf-with-dsym";')+' };')
    add('app'+mode,'isa = XCBuildConfiguration; name = '+mode+'; buildSettings = { ASSETCATALOG_COMPILER_APPICON_NAME = AppIcon; ASSETCATALOG_COMPILER_GLOBAL_ACCENT_COLOR_NAME = AccentColor; CODE_SIGN_STYLE = Automatic; DEVELOPMENT_TEAM = ""; CURRENT_PROJECT_VERSION = 1; MARKETING_VERSION = 1.0; GENERATE_INFOPLIST_FILE = NO; INFOPLIST_FILE = ResearchRadar/Info.plist; PRODUCT_BUNDLE_IDENTIFIER = com.bruce.EmbodiedResearchRadar; PRODUCT_NAME = "$(TARGET_NAME)"; TARGETED_DEVICE_FAMILY = "1,2"; SUPPORTED_PLATFORMS = "iphoneos iphonesimulator"; SUPPORTS_MACCATALYST = NO; LD_RUNPATH_SEARCH_PATHS = "$(inherited) @executable_path/Frameworks"; };')
for key in ['project','app']:
    add(key+'configs',f'isa = XCConfigurationList; buildConfigurations = ({uid(key+"Debug")},{uid(key+"Release")}); defaultConfigurationIsVisible = 0; defaultConfigurationName = Release;')
add('target',f'isa = PBXNativeTarget; buildConfigurationList = {uid("appconfigs")}; buildPhases = ({uid("sources")},{uid("frameworks")},{uid("resources")}); buildRules = (); dependencies = (); name = ResearchRadar; productName = ResearchRadar; productReference = {uid("product")}; productType = "com.apple.product-type.application";')
add('project',f'isa = PBXProject; attributes = {{ BuildIndependentTargetsInParallel = YES; LastUpgradeCheck = 1600; TargetAttributes = {{ {uid("target")} = {{ CreatedOnToolsVersion = 16.0; }}; }}; }}; buildConfigurationList = {uid("projectconfigs")}; compatibilityVersion = "Xcode 14.0"; developmentRegion = zh-Hans; hasScannedForEncodings = 0; knownRegions = ("zh-Hans",en,Base); mainGroup = {uid("main")}; productRefGroup = {uid("products")}; projectDirPath = ""; projectRoot = ""; targets = ({uid("target")});')
(root/'ResearchRadar.xcodeproj/project.pbxproj').write_text('// !$*UTF8*$!\n{archiveVersion = 1; classes = {}; objectVersion = 56; objects = {\n'+'\n'.join(objects)+'\n}; rootObject = '+uid('project')+'; }\n')
scheme=f'''<?xml version="1.0" encoding="UTF-8"?><Scheme LastUpgradeVersion="1600" version="1.3"><BuildAction parallelizeBuildables="YES" buildImplicitDependencies="YES"><BuildActionEntries><BuildActionEntry buildForTesting="YES" buildForRunning="YES" buildForProfiling="YES" buildForArchiving="YES" buildForAnalyzing="YES"><BuildableReference BuildableIdentifier="primary" BlueprintIdentifier="{uid('target')}" BuildableName="ResearchRadar.app" BlueprintName="ResearchRadar" ReferencedContainer="container:ResearchRadar.xcodeproj"/></BuildActionEntry></BuildActionEntries></BuildAction><LaunchAction buildConfiguration="Debug" selectedDebuggerIdentifier="Xcode.DebuggerFoundation.Debugger.LLDB" selectedLauncherIdentifier="Xcode.IDEFoundation.Launcher.LLDB" launchStyle="0" useCustomWorkingDirectory="NO" ignoresPersistentStateOnLaunch="NO" debugDocumentVersioning="YES" debugServiceExtension="internal" allowLocationSimulation="YES"><BuildableProductRunnable runnableDebuggingMode="0"><BuildableReference BuildableIdentifier="primary" BlueprintIdentifier="{uid('target')}" BuildableName="ResearchRadar.app" BlueprintName="ResearchRadar" ReferencedContainer="container:ResearchRadar.xcodeproj"/></BuildableProductRunnable></LaunchAction><ProfileAction buildConfiguration="Release" shouldUseLaunchSchemeArgsEnv="YES" savedToolIdentifier="" useCustomWorkingDirectory="NO" debugDocumentVersioning="YES"><BuildableProductRunnable runnableDebuggingMode="0"><BuildableReference BuildableIdentifier="primary" BlueprintIdentifier="{uid('target')}" BuildableName="ResearchRadar.app" BlueprintName="ResearchRadar" ReferencedContainer="container:ResearchRadar.xcodeproj"/></BuildableProductRunnable></ProfileAction><AnalyzeAction buildConfiguration="Debug"/><ArchiveAction buildConfiguration="Release" revealArchiveInOrganizer="YES"/></Scheme>'''
(root/'ResearchRadar.xcodeproj/xcshareddata/xcschemes/ResearchRadar.xcscheme').write_text(scheme)
info={'CFBundleDevelopmentRegion':'zh-Hans','CFBundleDisplayName':'具身研究台','CFBundleExecutable':'$(EXECUTABLE_NAME)','CFBundleIdentifier':'$(PRODUCT_BUNDLE_IDENTIFIER)','CFBundleInfoDictionaryVersion':'6.0','CFBundleName':'$(PRODUCT_NAME)','CFBundlePackageType':'APPL','CFBundleShortVersionString':'$(MARKETING_VERSION)','CFBundleVersion':'$(CURRENT_PROJECT_VERSION)','LSRequiresIPhoneOS':True,'UILaunchScreen':{},'UIApplicationSceneManifest':{'UIApplicationSupportsMultipleScenes':False},'NSLocalNetworkUsageDescription':'连接你的 Mac 研究台，同步论文、笔记、收藏与选题。','NSAppTransportSecurity':{'NSAllowsLocalNetworking':True},'UISupportedInterfaceOrientations':['UIInterfaceOrientationPortrait','UIInterfaceOrientationLandscapeLeft','UIInterfaceOrientationLandscapeRight'],'UISupportedInterfaceOrientations~ipad':['UIInterfaceOrientationPortrait','UIInterfaceOrientationPortraitUpsideDown','UIInterfaceOrientationLandscapeLeft','UIInterfaceOrientationLandscapeRight']}
info.update(NSBonjourServices=['_embodiedradar._tcp'],NSCameraUsageDescription='扫描 Mac 研究台的配对二维码。',CFBundleURLTypes=[{'CFBundleURLName':'ResearchRadar.Pairing','CFBundleURLSchemes':['embodiedradar']}])
(app/'Info.plist').write_bytes(plistlib.dumps(info))
(app/'Resources/PrivacyInfo.xcprivacy').write_bytes(plistlib.dumps({'NSPrivacyTracking':False,'NSPrivacyCollectedDataTypes':[],'NSPrivacyAccessedAPITypes':[{'NSPrivacyAccessedAPIType':'NSPrivacyAccessedAPICategoryUserDefaults','NSPrivacyAccessedAPITypeReasons':['CA92.1']}]}))
(app/'Resources/Assets.xcassets/Contents.json').write_text(json.dumps({'info':{'author':'xcode','version':1}}))
(app/'Resources/Assets.xcassets/AccentColor.colorset/Contents.json').write_text(json.dumps({'colors':[{'idiom':'universal','color':{'color-space':'srgb','components':{'red':'0.125','green':'0.357','blue':'0.278','alpha':'1.000'}}},{'idiom':'universal','appearances':[{'appearance':'luminosity','value':'dark'}],'color':{'color-space':'srgb','components':{'red':'0.570','green':'0.800','blue':'0.640','alpha':'1.000'}}}],'info':{'author':'xcode','version':1}}))
print('Xcode project generated.')
